  throw new Error('not implemented');
}","new_string":"export function parseRange(text) {
  const bad = () => new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  if (typeof text !== 'string') throw bad();
  const trimmed = text.trim();
  if (trimmed === '') throw bad();
  const parts = trimmed.split(/\s+/);
  if (parts.includes('*')) {
    if (parts.length !== 1) throw bad();
    return [];
  }
  const comparators = [];
  for (const part of parts) {
    const match = /^(>=|<=|>|<|=|\^|~|)(.*)$/.exec(part);
    const operator = match[1];
    const rest = match[2];
    let parsed;
    try {
      parsed = parseVersion(rest);
    } catch {
      throw bad();
    }
    if (operator === '^') {
      let upper;
      if (parsed.major !== 0) upper = `${parsed.major + 1}.0.0`;
      else if (parsed.minor !== 0) upper = `0.${parsed.minor + 1}.0`;
      else upper = `0.0.${parsed.patch + 1}`;
      comparators.push({ operator: '>=', version: rest }, { operator: '<', version: upper });
    } else if (operator === '~') {
      comparators.push(
        { operator: '>=', version: rest },
        { operator: '<', version: `${parsed.major}.${parsed.minor + 1}.0` },
      );
    } else {
      comparators.push({ operator: operator === '' ? '=' : operator, version: rest });
    }
  }
  return comparators;
}"}

